function messageBubble(m){const mine=m.sender_id===state.user?.id,deleted=!!(m.deleted||m.deleted_at);return `<article class="message-bubble ${mine?'mine':''} ${deleted?'deleted':''}" data-message-id="${escAttr(m.id)}" data-message-deleted="${deleted?'true':'false'}"><div class="message-meta"><button class="person-link" data-user="${escAttr(m.sender_id)}">${esc(m.sender_name)}</button><span class="message-meta-side"><small>${fmtTime(m.created_at)}</small>${m.can_delete&&!deleted?`<button type="button" class="message-delete" data-delete-message="${escAttr(m.id)}" aria-label="Eigene Nachricht löschen" title="Nachricht löschen">⌫</button>`:''}</span></div>${deleted?'<p class="message-deleted">Nachricht gelöscht</p>':`${m.body?`<p>${esc(m.body)}</p>`:''}${(m.media||[]).map((x,index)=>{const url=safeMediaUrlValue(x.url);return `<button type="button" class="private-message-media" data-message-media="${escAttr(url)}" aria-label="Chatbild ${index+1} von ${escAttr(m.sender_name)} vergrößert anzeigen"><img class="private-message-image" loading="lazy" decoding="async" src="${escAttr(url)}" alt="Privates Chatbild von ${escAttr(m.sender_name)}"></button>`}).join('')}<div class="message-reactions">${(m.reactions||[]).map(r=>`<button data-react="${esc(m.id)}" data-emoji="${esc(r.emoji)}" class="${r.mine?'active':''}">${esc(safeIcon(r.emoji,'👍'))} ${Number(r.count)||0}</button>`).join('')}<button class="reaction-add" data-react="${esc(m.id)}" data-emoji="👍" aria-label="Auf Nachricht reagieren">＋👍</button></div>`}</article>`}
function clearMessageImageSelection(){if(messaging.previewUrl){URL.revokeObjectURL(messaging.previewUrl);messaging.previewUrl=null}const input=$('#messageImage'),preview=$('#messageImagePreview');if(input)input.value='';if(preview){preview.hidden=true;preview.innerHTML=''}}
function wireMessageImagePreview(){const input=$('#messageImage'),preview=$('#messageImagePreview');if(!input||!preview)return;input.onchange=()=>{const file=input.files?.[0];if(messaging.previewUrl){URL.revokeObjectURL(messaging.previewUrl);messaging.previewUrl=null}preview.hidden=true;preview.innerHTML='';if(!file)return;const allowed=/^image\/(jpeg|png|webp|heic|heif)$/i.test(file.type),sizeOk=file.size<=8*1024*1024;if(!allowed||!sizeOk){input.value='';toast(!allowed?'Bitte JPG, PNG, WebP, HEIC oder HEIF verwenden.':'Das private Bild darf höchstens 8 MB groß sein.');return}messaging.previewUrl=URL.createObjectURL(file);preview.hidden=false;preview.innerHTML=`<div class="composer-image-preview-card"><img src="${escAttr(messaging.previewUrl)}" alt="Vorschau des ausgewählten Chatbildes"><div><b>${esc(file.name)}</b><small>${Math.max(1,Math.round(file.size/1024))} KB · wird erst beim Senden übertragen</small></div><button type="button" id="removeMessageImage" aria-label="Ausgewähltes Chatbild entfernen">×</button></div>`;$('#removeMessageImage').onclick=clearMessageImageSelection}}
