function renderMessageThread(){const c=messaging.thread,el=$('#messageThread');if(!el||!c)return;clearMessageImageSelection();el.closest('.messages-layout')?.classList.add('has-active-thread');const members=(c.members||[]).map(x=>x.name).join(', ');el.innerHTML=`<div class="thread-head"><button type="button" id="backToConversations" class="thread-back" aria-label="Zurück zur Unterhaltungsliste">←</button><div><h3>${esc(conversationName(c))}</h3><small>${esc(members)}${c.expires_at?` · läuft ab ${esc(c.expires_at)}`:''}</small></div></div><div class="messages-scroll" id="messagesScroll">${(c.messages||[]).map(messageBubble).join('')||'<p class="empty">Noch keine Nachrichten.</p>'}</div><form class="message-composer" id="messageComposer"><textarea id="messageBody" maxlength="6000" placeholder="Nachricht schreiben …" aria-label="Nachricht schreiben"></textarea><div class="composer-actions"><label class="upload-label">🖼 Bild<input id="messageImage" type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif"></label><button class="primary" type="submit">Senden</button></div><div id="messageImagePreview" class="composer-image-preview" aria-live="polite" hidden></div><small>Die Vorschau bleibt lokal. Private Bilder werden erst beim Senden übertragen, komprimiert und nur Mitgliedern dieser Unterhaltung ausgeliefert.</small></form>`;wirePersonLinks(el);wireMessageMediaViewer(el);el.querySelectorAll('[data-react]').forEach(b=>b.onclick=async()=>{try{await api('/api/messages/'+encodeURIComponent(b.dataset.react)+'/reactions',{method:'POST',body:JSON.stringify({emoji:b.dataset.emoji})});await openConversation(c.id)}catch(e){toast(e.message)}});el.querySelectorAll('[data-delete-message]').forEach(b=>b.onclick=async()=>{if(!confirm('Diese Nachricht für alle Teilnehmer löschen? Der Löschhinweis bleibt im Verlauf sichtbar.'))return;try{await api('/api/messages/'+encodeURIComponent(b.dataset.deleteMessage),{method:'DELETE'});await loadConversations();await openConversation(c.id);toast('Nachricht gelöscht')}catch(e){toast(e.message)}});const back=$('#backToConversations');if(back)back.onclick=()=>{messaging.activeId=null;messaging.thread=null;el.closest('.messages-layout')?.classList.remove('has-active-thread');renderConversationList();el.innerHTML='<div class="empty-state"><h3>Unterhaltung wählen</h3><p>Direktnachrichten und Gruppenchats erscheinen hier.</p></div>'};wireMessageImagePreview();$('#messageComposer').onsubmit=sendMessage;const sc=$('#messagesScroll');if(sc)sc.scrollTop=sc.scrollHeight}
async function sendMessage(e){e.preventDefault();const id=messaging.activeId,body=($('#messageBody')?.value||'').trim(),file=$('#messageImage')?.files?.[0],submit=e.submitter||$('#messageComposer button[type="submit"]');if(!body&&!file)return;try{if(submit)submit.disabled=true;if(file){const fd=new FormData();fd.append('image',file);fd.append('body',body);const r=await fetch('/api/messages/conversations/'+encodeURIComponent(id)+'/images',{method:'POST',credentials:'same-origin',headers:{'X-BUP-CSRF':await ensureCsrf()},body:fd});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||`Fehler ${r.status}`)}else await api('/api/messages/conversations/'+encodeURIComponent(id)+'/messages',{method:'POST',body:JSON.stringify({body})});clearMessageImageSelection();await loadConversations();await openConversation(id)}catch(err){toast(err.message);if(submit)submit.disabled=false}}
function conversationForm(prefillUserId=null){if(!state.user){loginModal();return}const people=(state.message_recipients||[]).filter(p=>p.id!==state.user.id);$('#modalContent').innerHTML=`<h2>Neue Unterhaltung</h2><div class="form"><label>Art<select id="conversationType"><option value="direct">Direktnachricht</option><option value="group">Gruppe</option></select></label><label>Titel (bei Gruppe)<input id="conversationTitle" maxlength="100" placeholder="z. B. Orga-Team Sommerfest"></label><label>Personen<select id="conversationPeople" multiple size="6">${people.map(p=>`<option value="${esc(p.id)}" ${prefillUserId===p.id?'selected':''}>${esc(p.name)} · Stufe ${p.trust_level}</option>`).join('')}</select></label><label>Ablaufdatum (optional für temporäre Gruppe)<input id="conversationExpiry" type="datetime-local"></label><button class="primary" id="saveConversation">Unterhaltung starten</button><small>Es erscheinen nur Personen, die aufgrund eines sichtbaren Profils oder eines gemeinsamen Spaces kontaktiert werden dürfen. Die Kommunikationsregeln der Empfänger werden zusätzlich serverseitig geprüft.</small></div>`;$('#modal').classList.add('show');$('#saveConversation').onclick=async()=>{try{const type=$('#conversationType').value,selected=[...$('#conversationPeople').selectedOptions].map(x=>x.value);const payload={type,title:$('#conversationTitle').value,expires_at:$('#conversationExpiry').value?new Date($('#conversationExpiry').value).toISOString():null};if(type==='direct')payload.direct_user_id=selected[0];else payload.member_ids=selected;const c=await api('/api/messages/conversations',{method:'POST',body:JSON.stringify(payload)});$('#modal').classList.remove('show');go('messages');await loadConversations();await openConversation(c.id)}catch(e){toast(e.message)}}}
