function filterCommunities(){
 const q=($('#communitySearch').value||'').trim().toLowerCase();
 const source=$('#communityFilter').value;
 const type=$('#communityTypeFilter').value;
 let items=state.communities.filter(c=>context.communityScope==='all'||placeDirectMatches(c,context.placeId));
 items=items.filter(c=>{
   const text=[c.name,c.type,...c.topics,...c.places.map(p=>p.name)].join(' ').toLowerCase();
   const okText=!q||text.includes(q);
   const okSource=source==='all'||c.source===source||(source==='mine'&&!!c.membership);
   const okType=type==='all'||c.type===type;
   return okText&&okSource&&okType;
 });
 $('#communityScopeLabel').textContent=context.communityScope==='all'?'Alle Ebenen':`Ebene: ${placeName(context.placeId)}`;
 $('#communityScopeHint').textContent=context.communityScope==='all'?'Räumlicher Filter ist aufgehoben.':`Es werden nur Communities angezeigt, die direkt ${placeName(context.placeId)} zugeordnet sind.`;
 $('#toggleCommunityScope').textContent=context.communityScope==='all'?`Zurück zu ${placeName(context.placeId)}`:'Alle Ebenen anzeigen';
 $('#communities-list').innerHTML=items.map(communityCard).join('')||'<p class="empty">Keine Communities für diese Filter gefunden.</p>';
 $('#communityResultCount').textContent=`${items.length} Treffer`;
 wireCommunityClicks();wireProjectClicks();wireFollowButtons($('#communities-list'));wireConnectionChips($('#communities-list'));
}
