 if((active==='rights'||active==='admin')&&state.user){api(`/api/permissions/${type}/${o.id}`).then(d=>{const box=$('[data-permission-box]');if(box){box.innerHTML=permissionPanel(d,type,o.id);wirePermissionPanel($('#modalContent'),type,o.id)}}).catch(e=>{const box=$('[data-permission-box]');if(box)box.innerHTML=`<div class="notice">${esc(e.message)}</div>`})};
 if((active==='moderation'||active==='admin')&&state.user&&(o.authz?.my_permissions||[]).includes('moderation.review')){api(`/api/moderation/${type}/${o.id}/reports`).then(d=>{const box=$('[data-moderation-box]');if(box){box.innerHTML=moderationPanel(d,type,o.id);wireModerationPanel($('#modalContent'),type,o.id)}}).catch(e=>{const box=$('[data-moderation-box]');if(box)box.innerHTML=`<div class="notice">${esc(e.message)}</div>`})};
 if(type==='event'&&active==='participants'&&state.user&&(o.authz?.my_permissions||[]).includes('event.manage_participants')){api(`/api/events/${o.id}/attendance-management`).then(d=>{const box=$('[data-attendance-management]');if(!box)return;const local=(d.local||[]).map(x=>`<div class="attendance-item"><span><b>${esc(x.name)}</b><small>${esc(x.status)}</small></span>${x.status==='requested'?`<span><button data-attendance-approve="local:${escAttr(x.user_id)}">Bestätigen</button><button data-attendance-reject="local:${escAttr(x.user_id)}">Ablehnen</button></span>`:''}</div>`).join('');const remote=(d.remote||[]).map(x=>`<div class="attendance-item"><span><b>Fediverse-Teilnahme</b><small>${esc(x.remote_actor_uri)} · ${esc(x.status)}</small></span>${x.status==='requested'?`<span><button data-attendance-approve="remote:${encodeURIComponent(x.remote_actor_uri)}">Bestätigen</button><button data-attendance-reject="remote:${encodeURIComponent(x.remote_actor_uri)}">Ablehnen</button></span>`:''}</div>`).join('');box.innerHTML=local+remote||'<p class="empty">Noch keine Teilnahmen.</p>';$$('[data-attendance-approve]').forEach(b=>b.onclick=()=>eventAttendanceDecision(o,b.dataset.attendanceApprove,'approve'));$$('[data-attendance-reject]').forEach(b=>b.onclick=()=>eventAttendanceDecision(o,b.dataset.attendanceReject,'reject'))}).catch(e=>{const box=$('[data-attendance-management]');if(box)box.innerHTML=`<div class="notice">${esc(e.message)}</div>`})};
