 $$('[data-task-release]').forEach(b=>b.onclick=async()=>{try{const fresh=await api(`/api/objects/${type}/${o.id}/tasks/${b.dataset.taskRelease}/assignee`,{method:'PUT',body:JSON.stringify({assignee_user_id:null})});renderObjectSpace(type,fresh,'tasks');toast('Aufgabe freigegeben')}catch(e){toast(e.message)}});
