 if($('#communityLogoInput'))$('#communityLogoInput').onchange=async e=>{try{await uploadApi(`/api/media/community/${c.id}/logo`,e.target.files[0]);await load();openCommunity(c.id,active,false);toast('Logo gespeichert')}catch(err){toast(err.message)}};
