function subspaceForm(parent){$('#modalContent').innerHTML=`<h2>Unterraum in ${esc(parent.name)} anlegen</h2><p class="notice">Ein Unterraum ist eine echte Community mit eigener Seite, bleibt aber mit ${esc(parent.name)} verknüpft. Orte und Themen werden standardmäßig vom Eltern-Space übernommen.</p><div class="form"><label>Name<input id="subspaceName"></label><label>Form<select id="subspaceType"><option>Gruppe</option><option>Team / Mannschaft</option><option>Arbeitsgruppe</option><option>Projekt-Community</option><option>Initiative</option></select></label><label>Beschreibung<textarea id="subspaceDescription"></textarea></label><label>Sichtbarkeit<select id="subspaceVisibility"><option value="public">Öffentlich</option><option value="unlisted">Nicht gelistet</option><option value="private">Privat</option></select></label><label>Beitritt<select id="subspaceAccess"><option value="open">Offen</option><option value="approval">Nur nach Freigabe</option><option value="invite">Nur Einladung</option><option value="trust">Ab Verifizierungsstufe</option></select></label><label>Mindest-Verifizierungsstufe<input id="subspaceTrust" type="number" min="1" max="3" value="1"></label><button class="primary" id="saveSubspace">Unterraum anlegen</button></div>`;$('#modal').classList.add('show');$('#subspaceVisibility').value=parent.visibility||'public';$('#subspaceAccess').value=parent.join_policy||'open';$('#subspaceTrust').value=parent.min_trust_level||1;$('#saveSubspace').onclick=async()=>{try{const child=await api(`/api/communities/${parent.id}/subspaces`,{method:'POST',body:JSON.stringify({name:$('#subspaceName').value,type:$('#subspaceType').value,description:$('#subspaceDescription').value,visibility:$('#subspaceVisibility').value,join_policy:$('#subspaceAccess').value,min_trust_level:Number($('#subspaceTrust').value)})});$('#modal').classList.remove('show');await load();openCommunity(child.id,'overview');toast('Unterraum angelegt')}catch(e){toast(e.message)}}}

async function decideJoin(communityId,userId,decision){try{await api(`/api/communities/${communityId}/join-requests/${userId}`,{method:'POST',body:JSON.stringify({decision})});await load();openCommunity(communityId,'about',false);toast(decision==='approve'?'Beitritt bestätigt':'Anfrage abgelehnt')}catch(e){toast(e.message)}}
function pollForm(c){$('#modalContent').innerHTML=`<h2>Umfrage erstellen</h2><div class="notice compact-notice">Umfragen laufen jetzt über den gemeinsamen PartiUp-Beteiligungskern. Dadurch können sie später um Phasen, Vorschläge, Ergebnisse und weitere Verfahren ergänzt werden.</div><div class="form"><label>Frage<input id="pollQuestion"></label><label>Antworten – eine pro Zeile<textarea id="pollOptions" placeholder="Option 1\nOption 2\nOption 3"></textarea></label><button class="primary" id="savePoll">Umfrage erstellen</button></div>`;$('#modal').classList.add('show');$('#savePoll').onclick=async()=>{try{const places=(c.places||[]).map(x=>x.id).filter(Boolean);if(!places.length)throw new Error('Der Space braucht mindestens einen Ort für einen Beteiligungsvorgang.');const question=$('#pollQuestion').value,options=$('#pollOptions').value.split('\n').map(x=>x.trim()).filter(Boolean);const created=await api('/api/participation',{method:'POST',body:JSON.stringify({name:question,type:'Umfrage',level:'Space',description:'Umfrage in '+c.name,places,communities:[c.id],owner_space_id:c.id,modules:{info:false,poll:true,vote:false,proContra:false,proposals:false},poll:{question,options},min_participant_trust:1,visibility:c.visibility==='private'?'private':'public',access_policy:'members'})});$('#modal').classList.remove('show');await load();openParticipation(created.id)}catch(e){toast(e.message)}}}
function registrationModal(){
 if(state.user){loginModal();return}
 $('#modalContent').innerHTML=`<h2>Konto erstellen</h2><p class="notice">Dein Profil und deine Nachrichtenkontakte sind zunächst eingeschränkt. Du kannst beides nach der Registrierung selbst freigeben. Die E-Mail-Adresse wird in diesem Prototyp noch nicht bestätigt.</p><div class="form"><label>Name<input id="registerName" autocomplete="name" maxlength="60"></label><label>E-Mail<input id="registerEmail" type="email" autocomplete="email" maxlength="254"></label><label>Passwort (mindestens 12 Zeichen)<input id="registerPassword" type="password" autocomplete="new-password" minlength="12" maxlength="128"></label><button class="primary" id="register" type="button">Konto erstellen</button><button id="showLogin" type="button">Bereits ein Konto? Anmelden</button></div>`;
 $('#modal').classList.add('show');
 $('#showLogin').onclick=loginModal;
 $('#register').onclick=async()=>{
  const button=$('#register');
  try{
   button.disabled=true;
   await api('/api/register',{method:'POST',body:JSON.stringify({name:$('#registerName').value,email:$('#registerEmail').value,password:$('#registerPassword').value})});
   $('#modal').classList.remove('show');
   await load();
   toast('Konto erstellt');
  }catch(err){toast(err.message);button.disabled=false}
 };
}
function loginModal(){if(state.user){const pref=state.user.preferences||{};$('#modalContent').innerHTML=`<div class="profile-head">${avatarHtml(state.user,'profile-avatar')}<div><h2>${esc(state.user.name)}</h2><p>${esc(state.user.email)} · Vertrauensstufe ${state.user.trust_level}</p></div></div><div class="media-actions"><label class="upload-label">Profilfoto ändern<input id="profileImageInput" type="file" accept="image/*"></label><small>Upload-Limit 12 MB; gespeichert werden optimierte WebP-Varianten statt des großen Originals.</small></div><div class="relation-box"><h3>Profil</h3><label>Über mich<textarea id="profileBio">${esc(state.user.bio||'')}</textarea></label><label>Ort<select id="profilePlace"><option value="">nicht angeben</option>${state.places.map(p=>`<option value="${escAttr(p.id)}" ${state.user.place_id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Interessen (Komma getrennt)<input id="profileInterests" value="${esc((state.user.interests||[]).join(', '))}"></label><button class="primary" id="saveProfileBasics">Profil speichern</button></div><div class="relation-box privacy-control-center"><div class="section-head"><div><h3>Profil & Sichtbarkeit</h3><small>Du entscheidest, wer welche Teile deiner Netzwerkidentität sehen darf. Objekt-Rechte können die Anzeige zusätzlich einschränken.</small></div></div><label>Gesamtes Profil sichtbar für<select id="profileVisibility">${privacySelectOptions(pref.profile_visibility||'network')}</select></label><div class="privacy-grid"><label>Bio<select id="bioVisibility">${privacySelectOptions(pref.bio_visibility||'network')}</select></label><label>Ort<select id="placeVisibility">${privacySelectOptions(pref.place_visibility||'private')}</select></label><label>Mitgliedschaften<select id="membershipsVisibility">${privacySelectOptions(pref.memberships_visibility||'private')}</select></label><label>Themen & Interessen<select id="interestsVisibility">${privacySelectOptions(pref.interests_visibility||'network')}</select></label><label>Projekte<select id="projectsVisibility">${privacySelectOptions(pref.projects_visibility||'network')}</select></label><label>Veranstaltungen / Teilnahmen<select id="attendanceVisibility">${privacySelectOptions(pref.event_attendance_visibility||'private')}</select></label><label>Gemeinsame Kontakte<select id="sharedConnectionsVisibility">${privacySelectOptions(pref.shared_connections_visibility||'network')}</select></label><label>Persönliche Aktivität<select id="profileActivityVisibility">${privacySelectOptions(pref.profile_activity_visibility||'network')}</select></label><label>Neue geteilte Inhalte standardmäßig<select id="profileActivityDefaultVisibility">${privacySelectOptions(pref.profile_activity_default_visibility||'network')}</select></label><label>Gefolgte Bereiche<select id="followsVisibility">${privacySelectOptions(pref.follows_visibility||'private')}</select></label><label>Weitere eigene Inhalte<select id="createdContentVisibility">${privacySelectOptions(pref.created_content_visibility||'network')}</select></label></div><div class="privacy-preview-actions"><b>Profil-Vorschau</b><div class="action-row"><button type="button" data-profile-preview="public">Öffentlich</button><button type="button" data-profile-preview="members">Als Mitglied</button><button type="button" data-profile-preview="network">Als Netzwerk/Freund</button></div><div id="profilePreviewResult" class="privacy-preview-result"><small>Die Vorschau wird serverseitig berechnet. Berechtigungen der verknüpften Originalobjekte bleiben zusätzlich maßgeblich.</small></div></div><button class="primary" id="savePrefs">Sichtbarkeit speichern</button><details class="privacy-audit"><summary>Letzte Sichtbarkeitsänderungen</summary><div id="profilePrivacyAudit"><small>Wird beim Öffnen geladen.</small></div></details></div><div class="relation-box"><h3>Kommunikation & Benachrichtigungen</h3><label>Wer darf dir Direktnachrichten schreiben?<select id="dmPermission"><option value="all" ${pref.dm_permission==='all'?'selected':''}>Alle Nutzer</option><option value="members" ${(!pref.dm_permission||pref.dm_permission==='members')?'selected':''}>Freunde oder Menschen aus gemeinsamen Communities</option><option value="nobody" ${pref.dm_permission==='nobody'?'selected':''}>Niemand</option></select></label><label>Wer darf dich in Gruppenchats einladen?<select id="groupInvites"><option value="all" ${pref.group_invites==='all'?'selected':''}>Alle Nutzer</option><option value="members" ${(!pref.group_invites||pref.group_invites==='members')?'selected':''}>Freunde oder Menschen aus gemeinsamen Communities</option><option value="nobody" ${pref.group_invites==='nobody'?'selected':''}>Niemand</option></select></label><label><input id="allowFollowers" type="checkbox" ${pref.allow_followers!==0?'checked':''}> Andere dürfen mir folgen</label><div class="check-grid prefs"><label><input id="notifyComments" type="checkbox" ${pref.notify_comments!==0?'checked':''}> Kommentare</label><label><input id="notifyMentions" type="checkbox" ${pref.notify_mentions!==0?'checked':''}> Erwähnungen</label><label><input id="notifyMessages" type="checkbox" ${pref.notify_messages!==0?'checked':''}> Nachrichten</label><label><input id="notifyEvents" type="checkbox" ${pref.notify_events!==0?'checked':''}> Veranstaltungen</label></div><button class="primary" id="saveCommunication">Kommunikation & Benachrichtigungen speichern</button></div><div class="relation-box"><h3>Folge ich</h3><p>${(state.following.communities?.length||0)} Communities · ${(state.following.places?.length||0)} Orte · ${(state.following.topics?.length||0)} Themen · ${(state.following.people?.length||0)} Menschen</p><small>Folgen steuert deinen persönlichen Feed; Mitgliedschaft und Rollen bleiben davon getrennt.</small></div><div class="notice">Änderungen werden erst über den jeweiligen Speichern-Button übernommen.</div><button id="logout" class="danger">Abmelden</button>`;if($('#profileImageInput'))$('#profileImageInput').onchange=async e=>{try{await uploadApi('/api/media/profile',e.target.files[0]);await load();loginModal();toast('Profilbild gespeichert')}catch(err){toast(err.message)}};if($('#saveProfileBasics'))$('#saveProfileBasics').onclick=async()=>{try{await api('/api/me/profile',{method:'PUT',body:JSON.stringify({bio:$('#profileBio').value,place_id:$('#profilePlace').value||null,interests:($('#profileInterests').value||'').split(',').map(x=>x.trim()).filter(Boolean)})});await load();loginModal();toast('Profil gespeichert')}catch(err){toast(err.message)}};$('#savePrefs').onclick=async()=>{try{await api('/api/preferences',{method:'PUT',body:JSON.stringify({dm_permission:$('#dmPermission').value,group_invites:$('#groupInvites').value,notify_comments:$('#notifyComments').checked,notify_mentions:$('#notifyMentions').checked,notify_messages:$('#notifyMessages').checked,notify_events:$('#notifyEvents').checked,profile_visibility:$('#profileVisibility').value,bio_visibility:$('#bioVisibility').value,place_visibility:$('#placeVisibility').value,memberships_visibility:$('#membershipsVisibility').value,follows_visibility:$('#followsVisibility').value,event_attendance_visibility:$('#attendanceVisibility').value,interests_visibility:$('#interestsVisibility').value,projects_visibility:$('#projectsVisibility').value,shared_connections_visibility:$('#sharedConnectionsVisibility').value,profile_activity_visibility:$('#profileActivityVisibility').value,profile_activity_default_visibility:$('#profileActivityDefaultVisibility').value,created_content_visibility:$('#createdContentVisibility').value,allow_followers:$('#allowFollowers').checked})});await load();toast('Einstellungen gespeichert')}catch(err){toast(err.message)}};$('#saveCommunication').onclick=()=>$('#savePrefs').click();document.querySelectorAll('[data-profile-preview]').forEach(b=>b.onclick=async()=>{try{const d=await api('/api/profile-preview/'+b.dataset.profilePreview);const out=$('#profilePreviewResult');if(!d.visible){out.innerHTML=`<div class="notice compact-notice">${esc(d.reason)}</div>`;return}const q=d.profile;out.innerHTML=`<div class="privacy-preview-card"><b>${esc(q.name)}</b>${q.bio?`<p>${esc(q.bio)}</p>`:''}<small>${q.place?`Ort: ${esc(q.place.name)} · `:''}${q.memberships?`${q.memberships.length} Mitgliedschaften · `:''}${q.projects?`${q.projects.length} Projekte · `:''}${q.event_attendance?`${q.event_attendance.length} Teilnahmen · `:''}${q.profile_activity?`${q.profile_activity.length} Aktivitäten`:''}</small><p class="compact-help">${esc(d.note||'')}</p></div>`}catch(e){toast(e.message)}});api('/api/profile-visibility/audit').then(rows=>{const el=$('#profilePrivacyAudit');if(el)el.innerHTML=(rows||[]).slice(0,12).map(r=>`<div class="relation-row"><span>${esc(r.field_name)}</span><small>${esc(privacyLabel(r.old_value))} → ${esc(privacyLabel(r.new_value))} · ${fmtTime(r.created_at)}</small></div>`).join('')||'<small>Noch keine Änderungen protokolliert.</small>'}).catch(()=>{});$('#logout').onclick=async()=>{await api('/api/logout',{method:'POST'});$('#modal').classList.remove('show');await load()}}else{$('#modalContent').innerHTML=`<h2>Anmelden</h2><p class="notice">Demo: <b>max@bottomupparti.local</b> / <b>demo123</b></p><div class="form"><label>E-Mail<input id="loginEmail" value="max@bottomupparti.local"></label><label>Passwort<input id="loginPassword" type="password" value="demo123"></label><button class="primary" id="login">Anmelden</button><button id="showRegistration" type="button">Konto erstellen</button></div>`;$('#showRegistration').onclick=registrationModal;$('#login').onclick=async()=>{try{await api('/api/login',{method:'POST',body:JSON.stringify({email:$('#loginEmail').value,password:$('#loginPassword').value})});$('#modal').classList.remove('show');await load();toast('Angemeldet')}catch(e){toast(e.message)}}}$('#modal').classList.add('show')}

const renderLoginModal=loginModal;
function deleteAccountConfirmation(){
 $('#modalContent').innerHTML=`<section class="privacy-account-deletion" aria-labelledby="deleteAccountTitle"><h2 id="deleteAccountTitle">Konto endgültig löschen</h2><div class="notice"><b>Bitte prüfe die Folgen vor der Bestätigung.</b><ul><li>Profil, Anmeldedaten, Sitzungen, Einstellungen und private Medien werden entfernt.</li><li>Mitgliedschaften, Freundschaften, Folgen, Teilnahmen und eigene Stimmen werden gelöscht.</li><li>Eigene Beiträge, Kommentare und Nachrichten werden anonymisiert, wenn Inhalte anderer Menschen daran hängen.</li><li>Notwendige Sicherheits- und Moderationsnachweise bleiben nur unter einem nicht mehr anmeldbaren technischen Verweis erhalten.</li><li>Bereits an andere Fediverse-Server übermittelte Kopien können nicht allein durch diese lokale Löschung entfernt werden.</li></ul></div><p>Du kannst vorher über „Eigene Daten herunterladen“ eine Kopie deiner Daten speichern.</p><div class="form"><label>Aktuelles Passwort<input id="deleteAccountPassword" type="password" autocomplete="current-password" required></label><label><input id="deleteAccountAcknowledge" type="checkbox"> Ich habe die Folgen gelesen und möchte mein Konto endgültig löschen.</label><p id="deleteAccountError" class="notice" role="alert" aria-live="polite" hidden></p><div class="action-row"><button type="button" id="cancelDeleteAccount">Abbrechen</button><button type="button" id="deleteAccount" class="danger" disabled>Konto endgültig löschen</button></div></div></section>`;
 const acknowledge=$('#deleteAccountAcknowledge'),submit=$('#deleteAccount');
 acknowledge.onchange=()=>{submit.disabled=!acknowledge.checked};
 $('#cancelDeleteAccount').onclick=()=>loginModal();
 submit.onclick=async()=>{const error=$('#deleteAccountError');error.hidden=true;error.textContent='';submit.disabled=true;try{const result=await api('/api/privacy/delete-account',{method:'POST',body:JSON.stringify({password:$('#deleteAccountPassword').value})});await load();$('#modalContent').innerHTML=`<h2>Konto gelöscht</h2><div class="notice">${esc(result.notice||'Dein Konto wurde gelöscht und du wurdest abgemeldet.')}</div><button type="button" class="primary" id="closeDeletedAccount">Schließen</button>`;$('#closeDeletedAccount').onclick=()=>$('#modal').classList.remove('show')}catch(e){error.textContent=e.message;error.hidden=false;submit.disabled=!acknowledge.checked}};
}
loginModal=function(){
 renderLoginModal();
 if(!state.user||$('#downloadPrivacyExport'))return;
 const logout=$('#logout');
 if(!logout)return;
 logout.insertAdjacentHTML('beforebegin',`<section class="relation-box privacy-data-export" aria-labelledby="privacyDataExportTitle"><h3 id="privacyDataExportTitle">Eigene Daten</h3><p>Du kannst die zu deinem Konto gespeicherten und mit ihm verknüpften Daten als maschinenlesbare JSON-Datei herunterladen.</p><a class="button-link primary privacy-download-button" id="downloadPrivacyExport" href="/api/privacy/export" download="partiup-meine-daten.json">Eigene Daten herunterladen</a><small>Passwortdaten, Sitzungsdaten und private Signaturschlüssel sind nicht enthalten. Eine Kontolöschung wird hierdurch nicht ausgelöst.</small></section><section class="relation-box privacy-danger-zone" aria-labelledby="deleteAccountEntryTitle"><h3 id="deleteAccountEntryTitle">Konto löschen</h3><p>Öffne zuerst die Folgenvorschau. Gelöscht wird erst nach einer weiteren ausdrücklichen Bestätigung mit deinem Passwort.</p><button type="button" id="openDeleteAccount" class="danger">Kontolöschung prüfen</button></section>`);
 $('#openDeleteAccount').onclick=deleteAccountConfirmation;
};

function personalNetworkModal(kind){if(!state.user){loginModal();return}let title='',body='';if(kind==='friends'){title='Freunde & Personenbeziehungen';const f=state.friendships||{friends:[],incoming:[],outgoing:[]};const followingPeople=(state.following.people||[]).map(x=>state.people.find(p=>String(p.id)===String(x.id))).filter(Boolean).filter(p=>![...f.friends,...f.incoming,...f.outgoing].some(x=>x.id===p.id));body=`<div class="network-summary"><span><b>${f.friends.length}</b> Freunde</span><span><b>${f.incoming.length}</b> offene Anfragen</span><span><b>${f.outgoing.length}</b> gesendet</span></div>${f.incoming.length?`<section class="network-section"><h3>Anfragen an dich</h3>${f.incoming.map(friendNetworkCard).join('')}</section>`:''}<section class="network-section"><h3>Freunde</h3>${f.friends.map(friendNetworkCard).join('')||'<p class="empty">Noch keine bestätigten Freundschaften.</p>'}</section>${f.outgoing.length?`<section class="network-section"><h3>Gesendete Anfragen</h3>${f.outgoing.map(friendNetworkCard).join('')}</section>`:''}${followingPeople.length?`<section class="network-section"><h3>Weitere gefolgte Personen</h3>${followingPeople.map(p=>friendNetworkCard({...p,friendship:{status:'none'}})).join('')}</section>`:''}`;}else if(kind==='memberships'){title='Meine Mitgliedschaften';body=(state.memberships||[]).map(m=>`<button class="community clickable" data-id="${escAttr(m.community_id)}"><span class="icon">${esc(safeIcon(m.icon,'✦'))}</span><span class="grow"><b>${esc(m.name)}</b><small>${esc(m.type)} · Rolle: ${esc(m.role)}</small></span></button>`).join('')||'<p class="empty">Noch keine Mitgliedschaften.</p>';}else{title='Gefolgte Bereiche';const fc=(state.following.communities||[]).map(f=>state.communities.find(c=>c.id===f.id)).filter(Boolean);const fp=(state.following.places||[]).map(f=>state.places.find(p=>p.id===f.id)).filter(Boolean);body=`<div class="notice compact-notice">Personen-Follows findest du unter <b>Freunde & Personenbeziehungen</b>. Hier stehen Orte, Themen und Communities.</div><h3>Communities</h3>${fc.map(communityCard).join('')||'<p class="empty">Keine.</p>'}<h3>Orte</h3><div class="follow-list entity-follow-list">${fp.map(p=>`<div class="followed-entity-row">${connectionChip('place',p,{icon:'📍'})}${followButton('place',p.id,'Folgen','follow-button compact')}</div>`).join('')||'<span>Keine.</span>'}</div><h3>Themen</h3><div class="follow-list entity-follow-list">${(state.following.topics||[]).map(t=>`<div class="followed-entity-row">${connectionChip('topic',t.id,{icon:'#'})}${followButton('topic',t.id,'Folgen','follow-button compact')}</div>`).join('')||'<span>Keine.</span>'}</div>`;}$('#modalContent').innerHTML=`<h2>${title}</h2>${body}`;$('#modal').classList.add('show');wireCommunityClicks();wirePersonLinks($('#modalContent'));wireConnectionChips($('#modalContent'));wireFriendNetworkActions($('#modalContent'));wireFollowButtons($('#modalContent'));}

async function notificationModal(){
 if(!state.user){loginModal();return}
 try{
  await load();
  const person=history.state?.person;
  if(person&&$('#person-space').classList.contains('active'))await openPerson(person,history.state.tab||'overview',false);
  const d=await api('/api/notifications');
  state.notification_count=d.unread;
  const count=$('#notificationCount');
  count.textContent=d.unread||'';
  count.style.display=d.unread?'inline-flex':'none';
  $('#modalContent').innerHTML=`<div class="section-head"><h2>Benachrichtigungen</h2>${d.unread?`<button id="readAll">Alle als gelesen</button>`:''}</div><div class="notification-list">${d.items.length?d.items.map(n=>`<button class="notification-item ${n.read_at?'':'unread'}" data-notification="${escAttr(n.id)}"><b>${esc(n.title)}</b><span>${esc(n.body||'')}</span><small>${fmtTime(n.created_at)}</small></button>`).join(''):'<p class="empty">Keine Benachrichtigungen.</p>'}</div>`;
  $('#modal').classList.add('show');
  if($('#readAll'))$('#readAll').onclick=async()=>{try{await api('/api/notifications/read',{method:'POST',body:JSON.stringify({})});await notificationModal()}catch(e){toast(e.message)}};
  $$('[data-notification]').forEach(b=>b.onclick=async()=>{try{await api('/api/notifications/read',{method:'POST',body:JSON.stringify({id:b.dataset.notification})});await notificationModal()}catch(e){toast(e.message)}});
 }catch(e){toast(e.message)}
}
function multiOptions(items,kind){const safeKind=safeClassToken(kind,['place','community','project','linkedProject','setup-place'],'place');return `<div class="check-grid">${items.map(x=>{const value=x&&typeof x==='object'?(x.id??x.name):x;const label=x&&typeof x==='object'?(x.name??x.id):x;const icon=x&&typeof x==='object'?safeIcon(x.icon,''):'';return `<label><input type="checkbox" name="${escAttr(safeKind)}" value="${escAttr(value??'')}"> ${icon?esc(icon)+' ':''}${esc(label??'')}</label>`}).join('')}</div>`}
function creationHub(){if(!state.user){loginModal();toast('Zum Erstellen bitte anmelden');return}$('#modalContent').innerHTML=`<h2>Erstellen</h2><p class="notice">Wähle nur den Objekttyp. Die jeweilige Erstellung bleibt kurz; komplexe Konfiguration folgt anschließend am Objekt selbst.</p><div class="creation-type-grid"><button data-create-type="community"><b>◈ Space / Community</b><small>Community, Verein, Gruppe, Initiative, Team …</small></button><button data-create-type="project"><b>◆ Projekt</b><small>Vorhaben mit Orten, Themen und Spaces verknüpfen</small></button><button data-create-type="event"><b>◷ Veranstaltung</b><small>Termin, Treffen oder Veranstaltung</small></button><button data-create-type="participation"><b>☑ Beteiligung</b><small>Information, Umfrage, Abstimmung, Pro & Contra</small></button></div>`;$('#modal').classList.add('show');$$('[data-create-type]').forEach(b=>b.onclick=()=>{const t=b.dataset.createType;if(t==='participation')participationForm();else createForm(t)})}
function createForm(type){if(!state.user){loginModal();toast('Zum Erstellen bitte anmelden');return}const title={community:'Space erstellen',event:'Event erstellen',project:'Projekt starten'}[type];if(type==='community'){$('#modalContent').innerHTML=`<h2>${title}</h2><p class="notice"><b>Minimal erstellen → direkt in den neuen Space → modular fertig einrichten.</b><br>Du musst jetzt nur die Basis angeben. Alles Weitere bleibt später änderbar.</p><div class="form"><label>Typ des Space<select id="formType"><option>Community</option><option>Gruppe</option><option>Verein</option><option>Organisation</option><option>Initiative</option><option>Netzwerk</option><option>Creator</option><option>Stadt / Institution</option><option>Projekt-Community</option><option>Team / Mannschaft</option><option>Arbeitsgruppe</option></select></label><label>Vorlage<select id="formTemplate"><option value="local_community">Lokale Community</option><option value="club">Verein</option><option value="initiative">Bürgerinitiative</option><option value="project_group">Projekt</option><option value="workgroup">Arbeitsgruppe</option><option value="public_institution">Öffentliche Institution</option><option value="interest_group">Offene Interessengruppe</option></select><small>Die Vorlage aktiviert nur sinnvolle Standardmodule. Alles bleibt veränderbar.</small></label><label>Name<input id="formName" maxlength="160"></label><label>Kurzbeschreibung<textarea id="formDescription" maxlength="500"></textarea></label><label>Übergeordneter Space (optional)<select id="formParent"><option value="">Kein übergeordneter Space</option>${state.communities.filter(c=>c.source==='native'&&['admin','moderator'].includes(c.membership)).map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></label><fieldset><legend>Ort – mindestens einer</legend>${multiOptions(state.places,'place')}</fieldset><label>Sichtbarkeit<select id="formVisibility"><option value="public">Öffentlich</option><option value="unlisted">Nicht gelistet</option><option value="private">Privat</option></select></label><div class="creator-preview">Erstellt von ${esc(state.user.name)} · Verifizierungsstufe ${state.user.trust_level}</div><label class="upload-label secondary">Optionales Bild/Icon nach Erstellung hochladen <span>→ im Einrichtungsmodus</span></label><button class="primary" id="saveCreate">Space erstellen</button></div>`;$('#modal').classList.add('show');$('#saveCreate').onclick=async()=>{try{const places=$$('input[name=place]:checked').map(x=>x.value);const payload={name:$('#formName').value,description:$('#formDescription').value,type:$('#formType').value,template_key:$('#formTemplate').value,visibility:$('#formVisibility').value,places,topics:[]};const parent=$('#formParent').value;const child=parent?await api(`/api/communities/${parent}/subspaces`,{method:'POST',body:JSON.stringify(payload)}):await api('/api/communities',{method:'POST',body:JSON.stringify(payload)});$('#modal').classList.remove('show');await load();openCommunity(child.id,'setup');toast('Space erstellt – jetzt kannst du ihn modular einrichten.')}catch(e){toast(e.message)}};return}
 const moduleDefs=type==='project'?[['tasks','Aufgaben & Verantwortlichkeiten',true],['updates','Updates',true],['events','Termine',true],['participation','Beteiligung',true],['discussion','Diskussion',true],['files','Dateien',true],['members','Team',true]]:[['tasks','Aufgaben & Verantwortlichkeiten',true],['participants','Teilnahme',true],['projects','Projekte',true],['discussion','Diskussion',true],['files','Dateien',true]];$('#modalContent').innerHTML=`<h2>${title}</h2><div class="form"><div class="notice compact-notice"><b>Als modularer Space anlegen.</b><br>Die Basis bleibt kurz; Funktionen können jetzt gewählt und später jederzeit geändert werden.</div><label>Name<input id="formName"></label><label>Kurzbeschreibung<textarea id="formDescription"></textarea></label><label>Sichtbarkeit<select id="formVisibility"><option value="public">Öffentlich</option><option value="unlisted">Nicht gelistet</option><option value="private">Privat</option></select></label>${type==='event'?'<label>Start (ISO 8601 mit Zeitzone)<input id="formStartAt" placeholder="2026-09-20T18:00:00+02:00"></label><label>Ende (ISO 8601 mit Zeitzone)<input id="formEndAt" placeholder="2026-09-20T21:00:00+02:00"></label><label>Teilnahme<select id="formAccess"><option value="open">Offen</option><option value="approval">Nur nach Freigabe</option><option value="invite">Nur Einladung</option><option value="members">Nur Community-Mitglieder</option><option value="trust">Ab Verifizierungsstufe</option></select></label><label>Mindest-Verifizierungsstufe<input id="formTrust" type="number" min="1" max="3" value="1"></label><label>Maximale Plätze<input id="formMax" type="number" min="1" placeholder="unbegrenzt"></label>':'<label>Zugang<select id="formAccess"><option value="open">Offen</option><option value="approval">Nur nach Freigabe</option><option value="invite">Nur Einladung</option><option value="trust">Ab Verifizierungsstufe</option></select></label><label>Mindest-Verifizierungsstufe<input id="formTrust" type="number" min="1" max="3" value="1"></label>'}<fieldset><legend>Module</legend><div class="module-selector">${moduleDefs.map(([id,label,on])=>`<label><input type="checkbox" name="objectModule" value="${id}" ${on?'checked':''}> ${label}</label>`).join('')}</div></fieldset><fieldset><legend>Wo ist das Objekt aktiv?</legend>${multiOptions(state.places,'place')}</fieldset><fieldset><legend>Themen</legend><div class="check-grid topics">${state.topics.map(t=>`<label><input type="checkbox" name="topic" value="${esc(t)}"> # ${esc(t)}</label>`).join('')}</div><input id="customTopics" placeholder="Weitere Themen, durch Komma getrennt"></fieldset><fieldset><legend>Mit Communities verknüpfen</legend>${multiOptions(state.communities.filter(c=>c.source==='native'),'community')}</fieldset>${type==='event'?`<fieldset><legend>Mit Projekten verknüpfen</legend>${multiOptions(state.projects,'linkedProject')}</fieldset>`:''}<button class="primary" id="saveCreate">${title}</button></div>`;$('#modal').classList.add('show');$('#saveCreate').onclick=async()=>{const places=$$('input[name=place]:checked').map(x=>x.value),topics=[...$$('input[name=topic]:checked').map(x=>x.value),...($('#customTopics').value||'').split(',').map(x=>x.trim()).filter(Boolean)],communities=$$('input[name=community]:checked').map(x=>x.value);const ownerSpace=$('#creationOwnerSpace')?.value||null;const modules={};$$('input[name=objectModule]').forEach(x=>modules[x.value]=x.checked);const payload={name:$('#formName').value,description:$('#formDescription').value,places,topics,communities,modules,visibility:$('#formVisibility').value,owner_space_id:ownerSpace,propagation_scope:$('#creationPropagation')?.value||null};if(type==='event'){payload.start_at=$('#formStartAt')?.value||'';payload.end_at=$('#formEndAt')?.value||'';payload.date=$('#formStartAt')?.value||'NEU · Demo';payload.attendance_policy=$('#formAccess').value;payload.min_trust_level=Number($('#formTrust').value);payload.max_participants=$('#formMax').value?Number($('#formMax').value):null;payload.projects=$$('input[name=linkedProject]:checked').map(x=>x.value)}else{payload.access_policy=$('#formAccess').value;payload.min_trust_level=Number($('#formTrust').value)}try{const created=await api('/api/'+(type==='event'?'events':'projects'),{method:'POST',body:JSON.stringify(payload)});$('#modal').classList.remove('show');await load();if(ownerSpace){await openCommunity(ownerSpace,type==='event'?'events':'projects',false)}else if(type==='event')openEvent(created.id);else openProject(created.id);toast(title+' gespeichert')}catch(e){toast(e.message)}}}
function setMobileMenu(open){document.querySelector('.app').classList.toggle('menu-open',open);const btn=$('#mobileMenu');if(btn){btn.setAttribute('aria-expanded',open?'true':'false');btn.setAttribute('aria-label',open?'Navigation schließen':'Navigation öffnen')}}
function syncMobileNav(page){$$('.mobile-bottom-nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(!['home','discover','communities','messages'].includes(page))$$('.mobile-bottom-nav [data-page]').forEach(b=>b.classList.remove('active'))}
$$('[data-page]').forEach(b=>b.addEventListener('click',()=>{go(b.dataset.page);syncMobileNav(b.dataset.page);setMobileMenu(false)}));$('#mobileMenu').onclick=()=>setMobileMenu(!document.querySelector('.app').classList.contains('menu-open'));$('#mobileMore').onclick=()=>setMobileMenu(true);$('#navBackdrop').onclick=()=>setMobileMenu(false);document.addEventListener('keydown',e=>{if(e.key==='Escape'){setMobileMenu(false);$('#modal').classList.remove('show')}});$('#search').oninput=renderDiscover;$$('.filter').forEach(b=>b.onclick=()=>{$$('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderDiscover()});$$('[data-discover-tab]').forEach(b=>b.onclick=()=>setDiscoverTab(b.dataset.discoverTab));if($('#showAllFediverseApps'))$('#showAllFediverseApps').onclick=()=>{fediverseShowAll=!fediverseShowAll;renderFediverseApps()};$('#communitySearch').oninput=filterCommunities;if($('#peopleSearch'))$('#peopleSearch').oninput=renderPeople;$('#communityFilter').onchange=filterCommunities;$('#communityTypeFilter').onchange=filterCommunities;$('#toggleCommunityScope').onclick=()=>{context.communityScope=context.communityScope==='all'?'place':'all';filterCommunities()};$('#identityButton').onclick=loginModal;$('#myFriendsLink').onclick=()=>personalNetworkModal('friends');$('#myMembershipsLink').onclick=()=>personalNetworkModal('memberships');$('#myFollowingLink').onclick=()=>personalNetworkModal('following');$('#manageBlockedPeople').onclick=()=>{setMobileMenu(false);blockedPeopleModal()};$('#notificationButton').onclick=notificationModal;$('#quickCreate').onclick=creationHub;$('#createCommunity').onclick=()=>createForm('community');if($('#createConversation'))$('#createConversation').onclick=()=>conversationForm();$('#createEvent').onclick=()=>createForm('event');$('#createProject').onclick=()=>createForm('project');$('#createParticipation').onclick=participationForm;$('#participationSearch').oninput=renderParticipation;$('#participationType').onchange=renderParticipation;$('#participationSource').onchange=renderParticipation;$$('.civic-level').forEach(b=>b.onclick=()=>{$$('.civic-level').forEach(x=>x.classList.remove('active'));b.classList.add('active');civicLevel=b.dataset.level;renderParticipation()});$('#closeModal').onclick=()=>$('#modal').classList.remove('show');$('#modal').onclick=e=>{if(e.target.id==='modal')$('#modal').classList.remove('show')};
async function openHashRoute(){let m=location.hash.match(/^#community\/([^/]+)(?:\/([^/]+))?/);if(m)return openCommunity(decodeURIComponent(m[1]),m[2]||'overview',false);m=location.hash.match(/^#person\/([^/]+)(?:\/([^/]+))?/);if(m)return openPerson(decodeURIComponent(m[1]),m[2]||'overview',false);m=location.hash.match(/^#topic\/([^/]+)/);if(m)return openTopic(decodeURIComponent(m[1]),false)}
window.addEventListener('popstate',()=>{if(location.hash.startsWith('#community/')||location.hash.startsWith('#person/')||location.hash.startsWith('#topic/'))openHashRoute();else go('home')});
load().then(()=>openHashRoute()).catch(err=>{document.body.innerHTML=`<main style="font-family:system-ui;padding:2rem"><h1>Backend nicht erreichbar</h1><p>Starte PartiUp mit <b>.\start-network.bat</b>.</p><pre>${esc(err.message)}</pre></main>`});
